306	    /// Constructs the receipt struct extracting the necessary receipt and
307	    /// contract address data out of the `cargo stylus deploy` output with the
308	    /// help of regex.
309	    async fn get_receipt(
310	        &self,
311	        output: std::process::Output,
312	    ) -> eyre::Result<Receipt> {
313	        // Convert output to string
314	        let output_str = String::from_utf8_lossy(&output.stdout);
315	
316	        // first we get the contract address
317	
318	        // The pattern matches the contract address that is preceeded by
319	        // ANSI escape codes (`cargo stylus deploy` outputs colored text).
320	        let contract_addr_regex =
321	            Regex::new(r"deployed code at address:\s*(?:\x1B\[[0-9;]*[a-zA-Z])*(0x[a-fA-F0-9]{40})")
322	                .context("Failed to create contract addr regex")?;
323	
324	        let contract_addr = contract_addr_regex
325	            .captures(&output_str)
326	            .and_then(|cap| cap.get(1))
327	            .context(format!(
328	                "No contract address found in output {output_str}"
329	            ))?
330	            .as_str();
331	        let contract_address =
332	            Address::from_str(contract_addr).context(format!(
333	                "Failed to parse contract address from string: {contract_addr}"
334	            ))?;
335	
336	        // Now we extract the transaction hash to fetch to receipt
337	
338	        let tx_hash_regex = Regex::new(r"0x[a-fA-F0-9]{64}")
339	            .context("Failed to create tx hash regex")?;
340	
341	        let tx_hash = tx_hash_regex
342	            .find(&output_str)
343	            .context(format!(
344	                "No transaction hash found in output {output_str}"
345	            ))?
346	            .as_str();
347	        let tx_hash = TxHash::from_str(tx_hash)
348	            .context("Failed to parse transaction hash")?;
349	
350	        // Finally we can fetch the receipt
351	
352	        let provider = ProviderBuilder::new()
353	            .with_recommended_fillers()
354	            .wallet(EthereumWallet::from(
355	                self.private_key.parse::<PrivateKeySigner>()?,
356	            ))
357	            .on_http(Url::from_str(&self.rpc_url).expect("invalid Url"));
358	
359	        let receipt = provider
360	            .get_transaction_receipt(tx_hash)
361	            .await
362	            .map_err(|e: RpcError<TransportErrorKind>| {
363	                eyre::eyre!("RPC error: {}", e)
364	            })?
365	            .ok_or_else(|| eyre::eyre!("Transaction receipt not found"))?;
366	
367	        Ok(Receipt { inner: receipt, contract_address })
368	    }
369	}

