105	            inner,
106	            marker: PhantomData,
107	        }
108	    }
109	
110	    /// Get the underlying `T` directly, bypassing the borrow checker.
111	    ///
112	    /// # Safety
113	    ///
114	    /// Enables storage aliasing.
115	    pub unsafe fn into_raw(self) -> T {
116	        self.inner
117	    }
118	}
