284	    /// The integer's bytes are written to slot `key`, starting `offset` bytes from the left.
285	    /// Note that the bytes must be written to a single, 32-byte EVM word.
286	    ///
287	    /// # Safety
288	    ///
289	    /// UB if the write would cross a word boundary.
290	    /// Aliases if called during the lifetime an overlapping accessor.
291	    ///
292	    /// [`SSTORE`]: https://www.evm.codes/#55
293	    unsafe fn set_uint<const B: usize, const L: usize>(
294	        host: VM,
295	        key: U256,
296	        offset: usize,
297	        value: Uint<B, L>,
298	    ) {
299	        debug_assert!(B.is_multiple_of(8));
300	        debug_assert!(B / 8 + offset <= 32);
301	
302	        if B == 256 {
303	            // ruint >= 1.17 requires BYTES == Self::BYTES in to_be_bytes.
304	            debug_assert_eq!(L, 4);
305	            let mut bytes = [0u8; 32];
306	            for (i, limb) in value.as_limbs().iter().rev().take(4).enumerate() {
307	                bytes[i * 8..(i + 1) * 8].copy_from_slice(&limb.to_be_bytes());
308	            }
309	            return Self::set_word(host, key, FixedBytes::from_slice(&bytes));
310	        }
311	
312	        let mut word = Self::get_word(host.clone(), key);
313	
314	        let value = value.to_be_bytes_vec();
315	        let dest = word[offset..].as_mut_ptr();
316	        ptr::copy(value.as_ptr(), dest, B / 8);
317	        Self::set_word(host, key, word);
318	    }
