 85	impl<K, V> StorageMap<K, V>
 86	where
 87	    K: StorageKey,
 88	    V: StorageType,
 89	{
 90	    /// Where in a word to access the wrapped value.
 91	    const CHILD_OFFSET: u8 = 32 - V::SLOT_BYTES as u8;
 92	
 93	    /// Gets an accessor to the element at the given key, or the zero-value if none is there.
 94	    /// Note: the accessor is protected by a [`StorageGuard`], which restricts its lifetime
 95	    /// to that of `&self`.
 96	    pub fn getter(&self, key: K) -> StorageGuard<'_, V> {
 97	        let slot = key.to_slot(self.slot.into());
 98	        unsafe { StorageGuard::new(V::new(slot, Self::CHILD_OFFSET, self.__stylus_host.clone())) }
 99	    }
100	
101	    /// Gets a mutable accessor to the element at the given key, or the zero-value if none is there.
102	    /// Note: the accessor is protected by a [`StorageGuardMut`], which restricts its lifetime
103	    /// to that of `&mut self`.
104	    pub fn setter(&mut self, key: K) -> StorageGuardMut<'_, V> {
105	        let slot = key.to_slot(self.slot.into());
106	        unsafe {
107	            StorageGuardMut::new(V::new(slot, Self::CHILD_OFFSET, self.__stylus_host.clone()))
108	        }
109	    }
110	
111	    /// Gets the element at the given key, or the zero value if none is there.
112	    pub fn get(&self, key: K) -> V::Wraps<'_> {
113	        let store = self.getter(key);
114	        unsafe { store.into_raw().load() }
115	    }
116	}
