118	impl<'a, K, V> StorageMap<K, V>
119	where
120	    K: StorageKey,

120	    K: StorageKey,
121	    V: SimpleStorageType<'a>,
122	{
123	    /// Sets the element at a given key, overwriting what may have been there.
124	    pub fn insert(&mut self, key: K, value: V::Wraps<'a>) {
125	        let mut store = self.setter(key);
126	        store.set_by_wrapped(value);
127	    }
128	
129	    /// Replace the element at the given key.
130	    /// Returns the old element, or the zero-value if none was there.
131	    pub fn replace(&mut self, key: K, value: V::Wraps<'a>) -> V::Wraps<'a> {
132	        let slot = key.to_slot(self.slot.into());
133	        // intentionally alias so that we can erase after load
134	        unsafe {
135	            let store = V::new(slot, Self::CHILD_OFFSET, self.__stylus_host.clone());
136	            let mut alias = V::new(slot, Self::CHILD_OFFSET, self.__stylus_host.clone());
137	            let prior = store.load();
138	            alias.set_by_wrapped(value);
139	            prior
140	        }
141	    }
142	
143	    /// Remove the element at the given key.
144	    /// Returns the element, or the zero-value if none was there.
145	    pub fn take(&mut self, key: K) -> V::Wraps<'a> {
146	        let slot = key.to_slot(self.slot.into());
147	        // intentionally alias so that we can erase after load
148	        unsafe {
149	            let store = V::new(slot, Self::CHILD_OFFSET, self.__stylus_host.clone());
150	            let mut alias = V::new(slot, Self::CHILD_OFFSET, self.__stylus_host.clone());
151	            let value = store.load();
152	            alias.erase();
153	            value
154	        }
155	    }
156	}
