 61	    /// Performs a raw deploy of another contract with the given `endowment` and init `code`.
 62	    /// Returns the address of the newly deployed contract, or the error data in case of failure.
 63	    ///
 64	    /// # Safety
 65	    ///
 66	    /// Note that the EVM allows init code to make calls to other contracts, which provides a vector
 67	    /// for reentrancy. This means that this method may enable storage aliasing if used in the
 68	    /// middle of a storage reference's lifetime and if reentrancy is allowed.
 69	    ///
 70	    /// For extra flexibility, this method does not clear the global storage cache.
 71	    pub unsafe fn deploy(
 72	        self,
 73	        host: &impl Host,
 74	        code: &[u8],
 75	        endowment: U256,
 76	    ) -> Result<Address, Vec<u8>> {
 77	        #[cfg(feature = "reentrant")]
 78	        match self.cache_policy {
 79	            CachePolicy::Clear => host.flush_cache(true),
 80	            CachePolicy::Flush => host.flush_cache(false),
 81	            CachePolicy::DoNothing => {}
 82	        }
 83	
 84	        let mut contract = Address::default();
 85	        let mut revert_data_len: usize = 0;
 86	
 87	        let endowment: B256 = endowment.into();
 88	        if let Some(salt) = self.salt {
 89	            host.create2(
 90	                code.as_ptr(),
 91	                code.len(),
 92	                endowment.as_ptr(),
 93	                salt.as_ptr(),
 94	                contract.as_mut_ptr(),
 95	                &mut revert_data_len as *mut _,
 96	            );
 97	        } else {
 98	            host.create1(
 99	                code.as_ptr(),
100	                code.len(),
101	                endowment.as_ptr(),
102	                contract.as_mut_ptr(),
103	                &mut revert_data_len as *mut _,
104	            );
105	        }
106	
107	        if contract.is_zero() {
108	            return Err(host.read_return_data(0, None));
109	        }
110	        Ok(contract)
111	    }
112	}
