 44	/// Prints the license and pragma given the CLI options.
 45	pub fn handle_license_and_pragma() {
 46	    let args = ExportCLI::parse();
 47	    match args.commands {
 48	        None => {
 49	            print_license_and_pragma(DEFAULT_LICENSE, DEFAULT_PRAGMA);
 50	        }
 51	        Some(ExportCommands::Abi { license, pragma }) => {
 52	            print_license_and_pragma(&license, &pragma);
 53	        }
 54	        _ => {}
 55	    }
