 61	    match args.commands {
 62	        None => {
 63	            print!("{}", AbiPrinter(T::fmt_abi));
 64	        }
 65	        Some(ExportCommands::Abi {
 66	            license: _,
 67	            pragma: _,
 68	        }) => {
 69	            print!("{}", AbiPrinter(T::fmt_abi));
 70	        }
 71	        Some(ExportCommands::Constructor) => {
 72	            print_constructor_signature::<T>();
 73	        }
