11	macro_rules! vm_hooks {
12	    (
13	        $(#[$block_meta:meta])*             // macros & docstrings to apply to all funcs
14	        module($link:literal, $stub:ident); // configures the wasm_import_module to link
15	
16	        // all the function declarations
17	        $($(#[$meta:meta])* $vis:vis fn $func:ident ($($arg:ident : $arg_type:ty),* ) $(-> $return_type:ty)?);*
18	    ) => {
19	        cfg_if! {
20	            if #[cfg(feature = "export-abi")] {
21	                // Generate a stub for each function.
22	                // We use a module for the block macros & docstrings.
23	                $(#[$block_meta])*
24	                mod $stub {
25	                    $(
26	                        $(#[$meta])*
27	                        #[allow(unused_variables, clippy::missing_safety_doc)]
28	                        $vis unsafe fn $func($($arg : $arg_type),*) $(-> $return_type)? {
29	                            unimplemented!()
30	                        }
31	                    )*
32	                }
33	                #[allow(unused_imports)]
34	                pub use $stub::*;
35	            } else if #[cfg(feature = "stylus-test")] {
36	                $(#[$block_meta])*
37	                $(
38	                    $(#[$meta])*
39	                    #[allow(unused, unused_variables, clippy::missing_safety_doc)]
40	                    $vis unsafe fn $func($($arg : $arg_type),*) $(-> $return_type)? {
41	                        panic!("HostIO functions are not available in stylus-test. Use TestVM functions instead.");
42	                    }
43	                )*
44	            } else {
45	                // Generate a wasm import for each function.
46	                $(#[$block_meta])*
47	                #[link(wasm_import_module = $link)]
48	                extern "C" {
49	                    $(
50	                        $(#[$meta])*
51	                        $vis fn $func($($arg : $arg_type),*) $(-> $return_type)?;
52	                    )*
53	                }
54	            }
55	        }
56	    };
57	}
