   140	fn user_entrypoint_fn(user_fn: Ident) -> Option<syn::ItemFn> {
   141	    let _ = user_fn;
   142	    cfg_if::cfg_if! {
   143	        if #[cfg(feature = "stylus-test")] {
   144	            None
   145	        } else {
   146	            #[allow(deprecated)]
