   148	            Some(parse_quote! {
   149	                #[no_mangle]
   150	                #[cfg(not(feature = "contract-client-gen"))]
   151	                pub extern "C" fn user_entrypoint(len: usize) -> usize {
   152	                    let host = stylus_sdk::host::VM { host: stylus_sdk::host::WasmVM{}};
   153	                    #deny_reentrant
   154	
   155	                    // The following call is a noop to ensure that pay_for_memory_grow is
   156	                    // referenced by the Stylus contract. Later, when the contract is activated,
   157	                    // Nitro will automatically add the calls pay_for_memory_grow when memory is
   158	                    // dynamically allocated. If we do not add this call here, the calls added by
   159	                    // Nitro will not work and activation will fail. This call costs 8700 Ink,
   160	                    // which is less than 1 Gas.
   161	                    host.pay_for_memory_grow(0);
   162	
   163	                    let input = host.read_args(len);
   164	                    let (data, status) = match #user_fn(input, host.clone()) {
   165	                        Ok(data) => (data, 0),
   166	                        Err(data) => (data, 1),
   167	                    };
   168	                    host.flush_cache(false /* do not clear */);
   169	                    host.write_result(&data);
   170	                    status
   171	                }
   172	            })
   173	        }
   174	    }
