 17	fn is_phantom_data(ty: &Type) -> bool {
 18	    if let Type::Path(type_path) = &ty {
 19	        return type_path
 20	            .path
 21	            .segments
 22	            .last()
 23	            .map(|s| s.ident == "PhantomData")
 24	            .unwrap_or(false);
 25	    }
 26	    false
