 29	/// Implementation of the [`#[storage]`][crate::storage] macro.
 30	pub fn storage(
 31	    attr: proc_macro::TokenStream,
 32	    input: proc_macro::TokenStream,
 33	) -> proc_macro::TokenStream {
 34	    if !attr.is_empty() {
 35	        emit_error!(
 36	            TokenStream::from(attr).span(),
 37	            "this macro is not configurable"
 38	        );
 39	    }
 40	
 41	    let item = parse_macro_input!(input as ItemStruct);
 42	    let ItemStruct {
 43	        attrs,
 44	        vis,
 45	        ident,
 46	        generics,
 47	        fields,
 48	        ..
 49	    } = item;
 50	
 51	    // Handle fields based on their type (named or unnamed)
 52	    let expanded_fields = match fields {
 53	        syn::Fields::Named(named_fields) => {
 54	            // Extract the original fields.
 55	            let mut original_fields = named_fields.named;
 56	            for field in original_fields.iter_mut() {
 57	                if field.ident != Some(STYLUS_CONTRACT_ADDRESS_FIELD.as_ident())
 58	                    && !is_phantom_data(&field.ty)
 59	                {
 60	                    field.attrs.push(parse_quote! {
 61	                        #[cfg(not(feature = "contract-client-gen"))]
 62	                    });
 63	                }
 64	            }
 65	            quote! {
 66	                #[cfg(not(feature = "contract-client-gen"))]
 67	                #STYLUS_HOST_FIELD: stylus_sdk::host::VM,
 68	                #original_fields
 69	            }
 70	        }
 71	        syn::Fields::Unnamed(_) => {
 72	            // Handle tuple structs if needed.
 73	            emit_error!(
 74	                fields.span(),
 75	                "Tuple structs are not supported by #[storage]"
 76	            );
 77	            return fields.to_token_stream().into();
 78	        }
 79	        syn::Fields::Unit => {
 80	            // Handle unit structs if needed.
 81	            quote! {
 82	                #[cfg(not(feature = "contract-client-gen"))]
 83	                #STYLUS_HOST_FIELD: stylus_sdk::host::VM,
 84	            }
 85	        }
 86	    };
 87	    // Inject the host trait generic into the item struct if not defined.
 88	    let mut host_injected_item: syn::ItemStruct = parse_quote! {
 89	        #(#attrs)*
 90	        #[cfg_attr(feature = "contract-client-gen", derive(Default))]
 91	        #vis struct #ident #generics {
 92	            #[cfg(feature = "contract-client-gen")]
 93	            #STYLUS_CONTRACT_ADDRESS_FIELD: stylus_sdk::alloy_primitives::Address,
 94	            #expanded_fields
 95	        }
 96	    };
 97	    let storage = Storage::from(&mut host_injected_item);
 98	    let mut output = host_injected_item.into_token_stream();
 99	    storage.to_tokens(&mut output);
100	    output.into()
101	}
