 1	fn get_client_funcs<E: InterfaceExtension>(
 2	    funcs: &[PublicFn<E::FnExt>],
 3	    public: bool,
 4	) -> (Vec<proc_macro2::TokenStream>, Vec<proc_macro2::TokenStream>) {
 5	    let (client_funcs_definitions, client_funcs_declarations): (
 6	            Vec<proc_macro2::TokenStream>,
 7	            Vec<proc_macro2::TokenStream>,
 8	        ) = funcs
 9	        .iter()
10	        .map(|func| {
11	            let func_name = func.name.clone();
12	
13	            let (context, call) = func.purity.get_context_and_call();
14	
15	            let inputs = func.inputs.iter().map(|input| {
16	                let name = input.name.clone();
17	                let ty = input.ty.clone();
18	                quote! { #name: #ty }
19	            });
20	            let inputs_names = func.inputs.iter().map(|input| {
21	                input.name.clone()
22	            });
23	            let inputs_types = func.inputs.iter().map(|input| {
24	                let ty = input.ty.clone();
25	                quote! { #ty }
26	            });
27	
28	            let (output_type, output_decoding) = get_output_type_and_decoding(&func.output);
29	
30	            let function_selector = func.function_selector();
31	
32	            let funcs_visibility = if public { quote! { pub } } else { quote! {} };
33	
34	            let signature = quote! {
35	                #funcs_visibility fn #func_name(
36	                    &self,
37	                    host: &impl stylus_sdk::stylus_core::host::Host,
38	                    context: impl #context,
39	                    #(#inputs,)*
40	                ) -> #output_type
41	            };
42	
43	            let definition = quote! {
44	                #signature {
45	                    let inputs = <<(#(#inputs_types,)*) as #AbiType>::SolType as #SolType>::abi_encode_params(&(#(#inputs_names,)*));
46	                    use stylus_sdk::function_selector;
47	                    let mut calldata = Vec::from(#function_selector);
48	                    calldata.extend(inputs);
49	                    let call_result = #call(host, context, self.#STYLUS_CONTRACT_ADDRESS_FIELD, &calldata)?;
50	                    #output_decoding
51	                }
52	            };
53	            let declaration = quote! {
54	                #signature;
55	            };
56	            (definition, declaration)
57	        })
58	        .unzip();
59	    (client_funcs_definitions, client_funcs_declarations)
60	}
