     4	//! Defines a builder struct that can create a [`crate::TestVM`] instance
     5	//! with convenient overrides for unit testing Stylus contracts.
     6	
     7	use std::{collections::HashMap, sync::Arc};
     8	
     9	use alloy_primitives::{Address, B256, U256};
    10	use alloy_provider::{network::Ethereum, RootProvider};
    11	use url::Url;
    12	
    13	use crate::{state::VMState, TestVM};
    14	
    15	/// Builder for constructing a [`crate::TestVM`] used for unit testing Stylus contracts built with
    16	/// the Stylus SDK. Allows for convenient customization of the contract's address, sender address,
    17	/// message value, and RPC URL if state forking is desired. These values and more can still be
    18	/// customized if the builder is not used, by instead invoking the corresponding method on the
    19	/// TestVM struct such as `vm.set_value(value)`.
    20	///
    21	/// # Example
    22	/// ```
    23	/// use alloy_primitives::{address, Address, U256};
    24	/// use stylus_test::{TestVM, TestVMBuilder};
    25	///
    26	/// let vm: TestVM = TestVMBuilder::new()
    27	///     .sender(address!("dCE82b5f92C98F27F116F70491a487EFFDb6a2a9"))
    28	///     .contract_address(address!("DeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF"))
    29	///     .value(U256::from(1))
    30	///     .rpc_url("http://localhost:8547")
    31	///     .build();
    32	/// ```
    33	#[derive(Default)]
    34	pub struct TestVMBuilder {
    35	    sender: Option<Address>,
    36	    value: Option<U256>,
    37	    contract_address: Option<Address>,
    38	    rpc_url: Option<String>,
    39	    storage: Option<HashMap<U256, B256>>,
    40	    provider: Option<Arc<RootProvider<Ethereum>>>,
    41	    block_num: Option<u64>,
    42	    chain_id: Option<u64>,
    43	}
    44	
    45	impl TestVMBuilder {
    46	    pub fn new() -> Self {
    47	        Self::default()
    48	    }
    49	    /// Sets the sender address for contract invocations.
    50	    pub fn sender(mut self, sender: Address) -> Self {
    51	        self.sender = Some(sender);
    52	        self
    53	    }
    54	    /// Sets the block number.
    55	    pub fn block_number(mut self, block_num: u64) -> Self {
    56	        self.block_num = Some(block_num);
    57	        self
    58	    }
    59	    /// Sets the chain id.
    60	    pub fn chain_id(mut self, id: u64) -> Self {
    61	        self.chain_id = Some(id);
    62	        self
    63	    }
    64	    /// Sets the storage mapping.
    65	    pub fn storage(mut self, mapping: HashMap<U256, B256>) -> Self {
    66	        self.storage = Some(mapping);
    67	        self
    68	    }
    69	    /// Sets the msg value for contract invocations.
    70	    pub fn value(mut self, value: U256) -> Self {
    71	        self.value = Some(value);
    72	        self
    73	    }
    74	    /// Sets the contract address.
    75	    pub fn contract_address(mut self, address: Address) -> Self {
    76	        self.contract_address = Some(address);
    77	        self
    78	    }
    79	    /// Sets the RPC URL to a Stylus-enabled Arbitrum chain for storage forking.
    80	    /// If specified, any calls to load storage will be made to the RPC URL at the TestVM's
    81	    /// specified contract address.
    82	    pub fn rpc_url(mut self, url: &str) -> Self {
    83	        let url = match Url::parse(url) {
    84	            Ok(url) => url,
    85	            Err(e) => {
    86	                panic!("Invalid RPC URL specified: {e}");
    87	            }
    88	        };
    89	        self.rpc_url = Some(url.to_string());
    90	        self.provider = Some(Arc::new(RootProvider::new_http(url)));
    91	        self
    92	    }
    93	    /// Returns and TestVM instance from the builder with the specified parameters.
    94	    pub fn build(self) -> TestVM {
    95	        let mut state = VMState::default();
    96	        if let Some(sender) = self.sender {
    97	            state.msg_sender = sender;
    98	        }
    99	        if let Some(value) = self.value {
   100	            state.msg_value = value;
   101	        }
   102	        if let Some(storage) = self.storage {
   103	            state.storage = storage;
   104	        }
   105	        if let Some(block_number) = self.block_num {
   106	            state.block_number = block_number;
   107	        }
   108	        if let Some(id) = self.chain_id {
   109	            state.chain_id = id;
   110	        }
   111	        if let Some(contract_address) = self.contract_address {
   112	            state.contract_address = contract_address;
   113	        }
   114	        state.provider = self.provider;
   115	        TestVM::from(state)
   116	    }
   117	}

