 50	
 51	/// A mock implementation of the [`stylus_core::host::Host`] trait for unit testing Stylus
 52	/// contracts.
 53	///
 54	/// # Examples
 55	/// ```
 56	/// use alloy_primitives::{Address, U256};
 57	/// use stylus_test::TestVM;
 58	///
 59	/// let vm = TestVM::new();
 60	///
 61	/// // Configure transaction state.
 62	/// vm.set_block_number(100);
 63	/// vm.set_sender(Address::from([1u8; 20]));
 64	/// vm.set_value(U256::from(1000));
 65	///
 66	/// // Mock contract calls.
 67	/// let contract = Address::from([2u8; 20]);
 68	/// let data = vec![0x01, 0x02, 0x03];
 69	/// vm.mock_call(contract, data.clone(), U256::from(1000), Ok(vec![0x04]));
 70	///
 71	/// // Get emitted logs after execution
 72	/// let logs = vm.get_emitted_logs();
 73	/// ```
 74	#[derive(Clone)]
 75	pub struct TestVM {
 76	    state: Rc<RefCell<VMState>>,
 77	}
 78	
 79	impl Default for TestVM {
 80	    fn default() -> Self {
 81	        Self::new()
 82	    }
 83	}
 84	
 85	impl From<VMState> for TestVM {
 86	    fn from(state: VMState) -> Self {
 87	        Self {
 88	            state: Rc::new(RefCell::new(state)),
 89	        }
 90	    }
 91	}
 92	
 93	impl TestVM {
 94	    /// Creates a new TestVM instance.
 95	    ///
 96	    /// # Examples
 97	    /// ```
 98	    /// use stylus_test::TestVM;
 99	    /// let vm = TestVM::new();
100	    /// ```
101	    pub fn new() -> Self {
102	        Self {
103	            state: Rc::new(RefCell::new(VMState::default())),
104	        }
105	    }
106	
107	    /// Returns a cloned snapshot of the internal test VM state,
108	    /// which contains storage, balances, and other mocked values
109	    /// in HashMaps and other simple data structures for inspection.
110	    pub fn snapshot(&self) -> VMState {
111	        self.state.borrow().clone()
112	    }
113	
114	    /// Sets the current block number.
115	    ///
