76	        .deploy()
77	        .await?
78	        .contract_address;
79	    let contract = Erc1967Example::new(contract_addr, &alice.wallet);
80	
81	    // verify initial balance is [`U256::ZERO`].
82	    let balance = contract.balanceOf(alice.address()).call().await?.balance;
83	    assert_eq!(balance, U256::ZERO);
84	
85	    let total_supply = contract.totalSupply().call().await?.totalSupply;
86	    assert_eq!(total_supply, U256::ZERO);
87	
88	    // mint 1000 tokens.
89	    let amount = U256::from(1000);
90	    watch!(contract.mint(alice.address(), amount))?;
91	
92	    // check that the balance can be accurately fetched through the proxy.
93	    let balance = contract.balanceOf(alice.address()).call().await?.balance;
94	    assert_eq!(balance, amount);
95	
96	    let total_supply = contract.totalSupply().call().await?.totalSupply;
97	    assert_eq!(total_supply, amount);
98	
99	    // check that the balance can be transferred through the proxy.
100	    let receipt = receipt!(contract.transfer(bob.address(), amount))?;
101	
102	    assert!(receipt.emits(Erc1967Example::Transfer {
103	        from: alice.address(),
104	        to: bob.address(),
105	        value: amount,
106	    }));
107	
108	    let balance = contract.balanceOf(alice.address()).call().await?.balance;
109	    assert_eq!(balance, U256::ZERO);
110	
111	    let balance = contract.balanceOf(bob.address()).call().await?.balance;
112	    assert_eq!(balance, amount);
113	
114	    let total_supply = contract.totalSupply().call().await?.totalSupply;
115	    assert_eq!(total_supply, amount);
116	
117	    Ok(())
118	}
