16	        .as_deployer()
17	        .with_constructor(constructor!(implementation_addr, alice.address()))
18	        .deploy()
19	        .await?;
20	    let contract =
21	        UpgradeableBeaconExample::new(receipt.contract_address, &alice.wallet);
22	    let contract_bob =
23	        UpgradeableBeaconExample::new(receipt.contract_address, &bob.wallet);
24	
25	    // check initial state.
26	    let implementation = contract.implementation().call().await?.implementation;
27	    assert_eq!(implementation, implementation_addr);
28	
29	    let owner = contract.owner().call().await?.owner;
30	    assert_eq!(owner, alice.address());
31	
32	    assert!(receipt.emits(UpgradeableBeaconExample::Upgraded {
33	        implementation: implementation_addr,
34	    }));
35	    assert!(receipt.emits(UpgradeableBeaconExample::OwnershipTransferred {
36	        previousOwner: Address::ZERO,
37	        newOwner: alice.address(),
38	    }));
39	
40	    // deploy new implementation.
41	    let new_implementation = erc20::deploy(&alice.wallet).await?;
42	
43	    // check that bob cannot upgrade.
44	    let err = send!(contract_bob.upgradeTo(new_implementation))
45	        .expect_err("should revert on non-owner");
46	    assert!(err.reverted_with(
47	        UpgradeableBeaconExample::OwnableUnauthorizedAccount {
48	            sender: bob.address(),
49	        }
50	    ));
51	
52	    // check that alice can upgrade.
53	    let receipt = receipt!(contract.upgradeTo(new_implementation))?;
54	
55	    assert!(receipt.emits(UpgradeableBeaconExample::Upgraded {
56	        implementation: new_implementation,
57	    }));
58	
59	    let implementation = contract.implementation().call().await?.implementation;
60	    assert_eq!(implementation, new_implementation);
61	
62	    Ok(())
63	}
