57	/// Non-canonical encoding of [`Signature`].
58	fn encode_signature(signature: Signature) -> [alloy_primitives::U256; 3] {
59	    let affine_r = signature.R.into_affine();
60	    [
61	        affine_r.x.into_bigint().into(),
62	        affine_r.y.into_bigint().into(),
63	        signature.s.into_bigint().into(),
64	    ]
65	}
