67	/// Non-canonical encoding of [`VerifyingKey`].
68	fn encode_verifying_key(
69	    verifying_key: VerifyingKey,
70	) -> [alloy_primitives::U256; 2] {
71	    let affine_verifying_key = verifying_key.point.into_affine();
72	    [
73	        affine_verifying_key.x.into_bigint().into(),
74	        affine_verifying_key.y.into_bigint().into(),
75	    ]
76	}
