367	impl ISafeErc20 for SafeErc20 {
368	    type Error = Error;
369	
370	    fn safe_transfer(
371	        &mut self,
372	        token: Address,
373	        to: Address,
374	        value: U256,
375	    ) -> Result<(), Self::Error> {
376	        let call = IERC20::transferCall { to, value };
377	
378	        Self::call_optional_return(token, &call)
379	    }
380	
381	    fn safe_transfer_from(
382	        &mut self,
383	        token: Address,
384	        from: Address,
385	        to: Address,
386	        value: U256,
387	    ) -> Result<(), Self::Error> {
388	        let call = IERC20::transferFromCall { from, to, value };
389	
390	        Self::call_optional_return(token, &call)
391	    }
392	
393	    fn try_safe_transfer(
394	        &mut self,
395	        token: Address,
396	        to: Address,
397	        value: U256,
398	    ) -> bool {
399	        self.safe_transfer(token, to, value).is_ok()
400	    }
401	
402	    fn try_safe_transfer_from(
403	        &mut self,
404	        token: Address,
405	        from: Address,
406	        to: Address,
407	        value: U256,
408	    ) -> bool {
409	        self.safe_transfer_from(token, from, to, value).is_ok()
410	    }
411	
412	    fn safe_increase_allowance(
413	        &mut self,
414	        token: Address,
415	        spender: Address,
416	        value: U256,
417	    ) -> Result<(), Self::Error> {
418	        let current_allowance = self.allowance(token, spender)?;
419	        let new_allowance = current_allowance
420	            .checked_add(value)
421	            .expect("should not exceed `U256::MAX` for allowance");
422	        self.force_approve(token, spender, new_allowance)
423	    }
424	
425	    fn safe_decrease_allowance(
426	        &mut self,
427	        token: Address,
428	        spender: Address,
429	        requested_decrease: U256,
430	    ) -> Result<(), Self::Error> {
431	        let current_allowance = self.allowance(token, spender)?;
432	
433	        if current_allowance < requested_decrease {
434	            return Err(SafeErc20FailedDecreaseAllowance {
435	                spender,
436	                current_allowance,
437	                requested_decrease,
438	            }
439	            .into());
440	        }
441	
442	        self.force_approve(
443	            token,
444	            spender,
445	            current_allowance - requested_decrease,
446	        )
447	    }
448	
449	    fn force_approve(
450	        &mut self,
451	        token: Address,
