570	    /// Imitates a Stylus high-level call, relaxing the requirement on the
571	    /// return value: if data is returned, it must not be `false`, otherwise
572	    /// calls are assumed to be successful.
573	    ///
574	    /// # Arguments
575	    ///
576	    /// * `token` - Address of the ERC-20 token contract.
577	    /// * `call` - [`IErc20`] call that implements [`SolCall`] trait.
578	    ///
579	    /// # Errors
580	    ///
581	    /// * [`Error::SafeErc20FailedOperation`] - If the `token` address is not a
582	    ///   contract, the contract fails to execute the call or the call returns
583	    ///   value that is not `true`.
584	    fn call_optional_return(
585	        token: Address,
586	        call: &impl SolCall,
587	    ) -> Result<(), Error> {
588	        if !token.has_code() {
589	            return Err(Error::SafeErc20FailedOperation(
590	                SafeErc20FailedOperation { token },
591	            ));
592	        }
593	
594	        let result = unsafe {
595	            RawCall::new()
596	                .limit_return_data(0, BOOL_TYPE_SIZE)
597	                .flush_storage_cache()
598	                .call(token, &call.abi_encode())
599	        };
600	
601	        match result {
602	            Ok(data)
603	                if data.is_empty()
604	                    || Bool::abi_decode(&data, true)
605	                        .is_ok_and(|success| success) =>
606	            {
607	                Ok(())
608	            }
609	            _ => Err(SafeErc20FailedOperation { token }.into()),
610	        }
611	    }
612	
613	    /// Returns the remaining number of ERC-20 tokens that `spender`
614	    /// will be allowed to spend on behalf of an owner.
615	    ///
616	    /// # Arguments
617	    ///
618	    /// * `&self` - Read access to the contract's state.
619	    /// * `token` - Address of the ERC-20 token contract.
620	    /// * `spender` - Account that will spend the tokens.
621	    ///
622	    /// # Errors
623	    ///
624	    /// * [`Error::SafeErc20FailedOperation`] - If the contract fails to read
625	    ///   `spender`'s allowance.
626	    fn allowance(
627	        &self,
628	        token: Address,
629	        spender: Address,
630	    ) -> Result<U256, Error> {
631	        if !Address::has_code(&token) {
632	            return Err(SafeErc20FailedOperation { token }.into());
633	        }
634	
635	        let erc20 = Erc20Interface::new(token);
636	        erc20.allowance(self, contract::address(), spender).map_err(|_e| {
637	            Error::SafeErc20FailedOperation(SafeErc20FailedOperation { token })
638	        })
639	    }
640	}
