271	        alice: Account,
272	        time_passed: u64,
273	    ) -> eyre::Result<()> {
274	        let timestamp = block_timestamp(&alice).await?;
275	        let start = timestamp - time_passed;
276	        let expected_amount = U256::from(std::cmp::min(
277	            BALANCE,
278	            BALANCE * time_passed / DURATION,
279	        ));
280	        let contract_addr = deploy(&alice, start, DURATION).await?;
281	        let erc20_address =
282	            deploy_erc20(&alice, contract_addr, U256::from(BALANCE)).await?;
283	
284	        let contract = VestingWallet::new(contract_addr, &alice.wallet);
285	        let erc20 = ERC20Mock::new(erc20_address, &alice.wallet);
286	
287	        let old_alice_balance =
288	            erc20.balanceOf(alice.address()).call().await?.balance;
289	        let old_contract_balance =
290	            erc20.balanceOf(contract_addr).call().await?.balance;
291	
292	        let released =
293	            contract.released_1(erc20_address).call().await?.released;
294	        let releasable =
295	            contract.releasable_1(erc20_address).call().await?.releasable;
296	        assert_eq!(U256::ZERO, released);
297	        assert_in_delta(expected_amount, releasable);
298	
299	        let receipt = receipt!(contract.release_1(erc20_address))?;
300	
301	        let alice_balance =
302	            erc20.balanceOf(alice.address()).call().await?.balance;
303	        let contract_balance =
304	            erc20.balanceOf(contract_addr).call().await?.balance;
305	        let released =
306	            contract.released_1(erc20_address).call().await?.released;
307	        let releasable =
308	            contract.releasable_1(erc20_address).call().await?.releasable;
309	        assert_in_delta(expected_amount, released);
310	        assert_in_delta(U256::ZERO, releasable);
311	        assert_in_delta(old_alice_balance + released, alice_balance);
312	        assert_in_delta(old_contract_balance - released, contract_balance);
313	
314	        assert!(receipt.emits(VestingWallet::ERC20Released {
315	            token: erc20_address,
316	            amount: released
317	        }));
318	
319	        Ok(())
320	    }
