69	        alice.deploy_proxy(logic_addr, alice.address()).await?.contract_address;
70	
71	    let logic = UUPSProxyErc20Example::new(logic_addr, &alice.wallet);
72	    let proxy = Erc1967Example::new(proxy_addr, &alice.wallet);
73	
74	    // assert proxy and logic initialized correctly
75	    assert_eq!(logic_addr, proxy.implementation().call().await?.implementation);
76	    assert_eq!(
