78	        proxy.UPGRADE_INTERFACE_VERSION().call().await?.version,
79	    );
80	    assert_eq!(
81	        UPGRADE_INTERFACE_VERSION,
82	        logic.UPGRADE_INTERFACE_VERSION().call().await?.version,
83	    );
84	    assert_eq!(
85	        uups_upgradeable::VERSION_NUMBER,
86	        U32::from(proxy.getVersion().call().await?.version),
87	    );
88	    assert_eq!(
89	        uups_upgradeable::VERSION_NUMBER,
90	        U32::from(logic.getVersion().call().await?.version),
91	    );
92	    // check that state is set correctly
93	    assert_eq!(alice.address(), proxy.owner().call().await?.owner);
