    20	impl EddsaExample {
    21	    /// Verification api is slightly different from canonical implementation
    22	    /// missing compressed points.
    23	    fn verify(
    24	        &self,
    25	        verifying_key: [alloy_primitives::U256; 2],
    26	        signature: [alloy_primitives::U256; 3],
    27	        message: Bytes,
    28	    ) -> bool {
    29	        let verifying_key = VerifyingKey::from_affine(AffinePoint {
    30	            x: Fp256::<Curve25519FqParam>::from_bigint(verifying_key[0].into()),
    31	            y: Fp256::<Curve25519FqParam>::from_bigint(verifying_key[1].into()),
    32	        });
    33	
    34	        let signature = Signature::from_affine_R_s(
    35	            AffinePoint {
    36	                x: Fp256::<Curve25519FqParam>::from_bigint(signature[0].into()),
    37	                y: Fp256::<Curve25519FqParam>::from_bigint(signature[1].into()),
    38	            },
    39	            Scalar::from_bigint(signature[2].into()),
    40	        );
    41	
    42	        verifying_key.is_valid(&message, &signature)
    43	    }
