24	#[derive(SolidityError, Debug)]
25	enum Error {
26	    ExceededCap(capped::ERC20ExceededCap),
27	    InvalidCap(capped::ERC20InvalidCap),
28	    InsufficientBalance(erc20::ERC20InsufficientBalance),
29	    InvalidSender(erc20::ERC20InvalidSender),
30	    InvalidReceiver(erc20::ERC20InvalidReceiver),
31	    InsufficientAllowance(erc20::ERC20InsufficientAllowance),
32	    InvalidSpender(erc20::ERC20InvalidSpender),
33	    InvalidApprover(erc20::ERC20InvalidApprover),
34	    EnforcedPause(pausable::EnforcedPause),
35	    ExpectedPause(pausable::ExpectedPause),
36	}
37	
38	impl From<capped::Error> for Error {
39	    fn from(value: capped::Error) -> Self {
40	        match value {
41	            capped::Error::ExceededCap(e) => Error::ExceededCap(e),
42	            capped::Error::InvalidCap(e) => Error::InvalidCap(e),
43	        }
44	    }
45	}
46	
47	impl From<erc20::Error> for Error {
48	    fn from(value: erc20::Error) -> Self {
49	        match value {
50	            erc20::Error::InsufficientBalance(e) => {
51	                Error::InsufficientBalance(e)
52	            }
53	            erc20::Error::InvalidSender(e) => Error::InvalidSender(e),
54	            erc20::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
55	            erc20::Error::InsufficientAllowance(e) => {
56	                Error::InsufficientAllowance(e)
57	            }
58	            erc20::Error::InvalidSpender(e) => Error::InvalidSpender(e),
59	            erc20::Error::InvalidApprover(e) => Error::InvalidApprover(e),
60	        }
61	    }
62	}
63	
64	impl From<pausable::Error> for Error {
65	    fn from(value: pausable::Error) -> Self {
66	        match value {
67	            pausable::Error::EnforcedPause(e) => Error::EnforcedPause(e),
68	            pausable::Error::ExpectedPause(e) => Error::ExpectedPause(e),
69	        }
70	    }
71	}
