84	impl Erc20Example {
85	    #[constructor]
86	    pub fn constructor(
87	        &mut self,
88	        name: String,
89	        symbol: String,
90	        cap: U256,
91	    ) -> Result<(), Error> {
92	        self.metadata.constructor(name, symbol);
