97	    // Add token minting feature.
98	    //
99	    // Make sure to handle `Capped` properly. You should not call
100	    // [`Erc20::_update`] to mint tokens -- it will the break `Capped`
101	    // mechanism.
102	    fn mint(&mut self, account: Address, value: U256) -> Result<(), Error> {
103	        self.pausable.when_not_paused()?;
104	        let max_supply = self.capped.cap();
105	
106	        // Overflow check required.
107	        let supply = self
108	            .erc20
109	            .total_supply()
110	            .checked_add(value)
111	            .expect("new supply should not exceed `U256::MAX`");
112	
113	        if supply > max_supply {
114	            return Err(capped::Error::ExceededCap(
115	                capped::ERC20ExceededCap {
116	                    increased_supply: supply,
117	                    cap: max_supply,
118	                },
119	            ))?;
120	        }
121	
122	        self.erc20._mint(account, value)?;
123	        Ok(())
124	    }
125	
126	    /// WARNING: These functions are intended for **testing purposes** only. In
127	    /// **production**, ensure strict access control to prevent unauthorized
128	    /// pausing or unpausing, which can disrupt contract functionality. Remove
129	    /// or secure these functions before deployment.
130	    fn pause(&mut self) -> Result<(), Error> {
131	        Ok(self.pausable.pause()?)
132	    }
133	
134	    fn unpause(&mut self) -> Result<(), Error> {
135	        Ok(self.pausable.unpause()?)
136	    }
137	}
