753	            Transfer::Single { id, value } => receiver
754	                .on_erc_1155_received(call, operator, from, id, value, data),
755	
756	            Transfer::Batch { ids, values } => receiver
757	                .on_erc_1155_batch_received(
758	                    call, operator, from, ids, values, data,
759	                ),
760	        };
761	
762	        let id = match result {
763	            Ok(id) => id,
764	            Err(e) => {
765	                if let call::Error::Revert(ref reason) = e {
