  7	/// Helper for reading and writing primitive types to specific storage slots.
  8	///
  9	/// Storage slots are often used to avoid storage conflict when dealing with
 10	/// upgradeable contracts. This library helps with reading and writing to such
 11	/// slots without the need for low-level operations.
 12	///
 13	/// The functions in this library return appropriate storage types that contain
 14	/// a `value` member that can be used to read or write.
 15	///
 16	/// Example usage to set ERC-1967 implementation slot:
 17	///
 18	/// ```rust
 19	/// extern crate alloc;
 20	///
 21	/// use alloc::{vec, vec::Vec};
 22	/// use alloy_primitives::{b256, Address, B256};
 23	/// use openzeppelin_stylus::utils::storage_slot::StorageSlot;
 24	/// use stylus_sdk::{storage::StorageAddress, prelude::*};
 25	///
 26	/// const IMPLEMENTATION_SLOT: B256 = b256!("0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc");
 27	///
 28	/// #[storage]
 29	/// #[entrypoint]
 30	/// pub struct Erc1967;
 31	///
 32	/// #[public]
 33	/// impl Erc1967 {
 34	///     fn get_implementation(&self) -> Address {
 35	///         return StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).get();
 36	///     }
 37	///
 38	///     fn set_implementation(&mut self, new_implementation: Address) {
 39	///         assert!(new_implementation.has_code());
 40	///         StorageSlot::get_slot::<StorageAddress>(IMPLEMENTATION_SLOT).set(new_implementation);
 41	///     }
 42	/// }
 43	/// ```
 44	pub struct StorageSlot;
 45	
 46	impl StorageSlot {
 47	    /// Returns a [`StorageType`] located at `slot`.
 48	    ///
 49	    /// # Arguments
 50	    ///
 51	    /// * `slot` - The slot to get the address from.
 52	    #[must_use]
 53	    pub fn get_slot<ST: StorageType>(slot: impl Into<U256>) -> ST {
 54	        // TODO: Remove this once we have a proper way to inject the host for
 55	        // custom storage slot access.
 56	        // This has been implemented on Stylus SDK 0.10.0.
 57	
 58	        // Priority order:
 59	        // 1. If wasm32 target -> always use tuple syntax (highest priority).
 60	        // 2. If reentrant feature enabled (on non-wasm32) -> use struct syntax.
 61	        // 3. If non-wasm32 without export-abi -> use struct syntax.
 62	        // 4. Everything else -> use tuple syntax.
 63	
 64	        #[cfg(all(
 65	            not(target_arch = "wasm32"),
 66	            any(feature = "reentrant", not(feature = "export-abi"))
 67	        ))]
 68	        let host =
 69	            VM { host: alloc::boxed::Box::new(stylus_sdk::host::WasmVM {}) };
 70	
 71	        #[cfg(not(all(
 72	            not(target_arch = "wasm32"),
 73	            any(feature = "reentrant", not(feature = "export-abi"))
 74	        )))]
 75	        let host = VM(stylus_sdk::host::WasmVM {});
 76	
 77	        // SAFETY: Truncation is safe here because ST::SLOT_BYTES is never
 78	        // larger than 32, so the subtraction cannot underflow and the
 79	        // cast is always valid.
 80	        #[allow(clippy::cast_possible_truncation)]
 81	        unsafe {
 82	            ST::new(slot.into(), SLOT_BYTE_SPACE - ST::SLOT_BYTES as u8, host)
 83	        }
 84	    }
