/^(#\[[^]]*\][ \t]*)*pub struct [A-Za-z0-9_]+/ { show=1; hdr=NR": "$0; printed=0; if ($0 ~ /;[ \t]*$/) { print F":"hdr; show=0 } }
show && /^[ \t]+(pub(\([a-z]+\))? )?[a-z_0-9]+:/ { if (!printed) { print F":"hdr; printed=1 } print F":"NR": "$0 }
show && /^}/ { show=0 }
' "$f"; done | sed 's/  */ /g' | cut -c1-150 | head -230

