use strict;
use warnings;
binmode(STDOUT, ':utf8');

# Usage: perl accessors.pl FILE...   (run from /tmp/bench/v030)
# Prints per-file counts of host accessor call sites, split prod/test.
my %tot;      # category => [prod, test]
my @rows;
for my $file (@ARGV) {
    open(my $fh, '<', $file) or die "cannot open $file: $!";
    my @lines = <$fh>;
    close $fh;
    my $cfg_test = @lines + 1;
    for my $i (0 .. $#lines) {
        if ($lines[$i] =~ /^\s*#\[cfg\(test\)\]/) { $cfg_test = $i + 1; last; }
    }
    my %c;
    for my $i (0 .. $#lines) {
        my $ln = $lines[$i];
        next if $ln =~ /^\s*(\/\/|\/\/\/|\/\/!)/;   # comments and doc comments
        next if $ln =~ /^\s*(pub\s+)?use\s/;        # imports
        my $is_test = ($i + 1) >= $cfg_test ? 1 : 0;
        my $cat;
        my $s = $ln;
        while ($s =~ /(?<![A-Za-z0-9_])(msg|block|contract|evm|call)::([a-z_][a-z0-9_]*)/g) {
            my $k = "$1::$2";
            $c{$k}{$is_test}++;
        }
        while ($s =~ /(?<![A-Za-z0-9_.:])(call)\(/g) {
            $c{"call(bare)"}{$is_test}++;
        }
        while ($s =~ /\.has_code\(\)/g) {
            $c{"has_code"}{$is_test}++;
        }
        while ($s =~ /StorageSlot::get_slot/g) {
            $c{"get_slot"}{$is_test}++;
        }
    }
    my $name = $file;
    $name =~ s{^\./}{};
    for my $k (sort keys %c) {
        my $p = $c{$k}{0} // 0;
        my $t = $c{$k}{1} // 0;
        $tot{$k}[0] += $p;
        $tot{$k}[1] += $t;
    }
    my $pp = 0; my $tt = 0;
    for my $k (keys %c) { $pp += $c{$k}{0} // 0; $tt += $c{$k}{1} // 0; }
    push @rows, [$name, \%c, $pp, $tt] if $pp + $tt > 0;
}

print "| File | msg::* | block::* | contract::* | evm::* | call::* / call(...) | has_code | get_slot | Prod | Test |\n";
print "|---|---|---|---|---|---|---|---|---|---|\n";
for my $r (sort { $a->[0] cmp $b->[0] } @rows) {
    my ($name, $c, $pp, $tt) = @$r;
    my $grp = sub {
        my ($re) = @_;
        my ($p, $t) = (0, 0);
        for my $k (keys %$c) { next unless $k =~ $re; $p += $c->{$k}{0} // 0; $t += $c->{$k}{1} // 0; }
        return $t ? "$p (+$t test)" : ($p ? "$p" : "-");
    };
    printf "| %s | %s | %s | %s | %s | %s | %s | %s | %d | %d |\n",
        "`$name`", $grp->(qr/^msg::/), $grp->(qr/^block::/), $grp->(qr/^contract::/),
        $grp->(qr/^evm::/), $grp->(qr/^call(::|\()/), $grp->(qr/^has_code$/), $grp->(qr/^get_slot$/),
        $pp, $tt;
}
print "\nDistinct accessor functions (occurrences; production / test):\n\n";
for my $k (sort { ($tot{$b}[0]+$tot{$b}[1]) <=> ($tot{$a}[0]+$tot{$a}[1]) || $a cmp $b } keys %tot) {
    printf "- `%s`: %d production, %d test\n", $k, $tot{$k}[0], $tot{$k}[1];
}

