use strict;
use warnings;
binmode(STDIN, ':utf8');
binmode(STDOUT, ':utf8');
my $text = do { local $/; <STDIN> };
my $old = '| `contract1.sender(...)` / `contract2` (two contract handles in one test) | 12 / 12 |';
my $new = '| `contract1.sender(...)` (lines) / any `contract2` text (lines) | 12 / 12 |';
my $count = () = $text =~ /\Q$old\E/g;
die "pattern found $count times\n" unless $count == 1;
$text =~ s/\Q$old\E/$new/;
print $text;

use strict;
use warnings;
binmode(STDOUT, ':utf8');

# Input: TSV rows (file, line, test, contract, description, class, expected), no header.
my $in = shift @ARGV or die "usage: e2e_tables.pl rows.tsv\n";
open(my $fh, '<', $in) or die "cannot open $in: $!";

my %mixed = map { $_ => 1 } (
    'examples/erc721/tests/erc721.rs|burns',
    'examples/erc721/tests/erc721.rs|burns_approved_token',
    'examples/erc721/tests/erc721.rs|burns_approved_for_all',
    'examples/erc721/tests/erc721.rs|token_of_owner_by_index_after_transfer_to_another_account',
    'examples/erc721/tests/erc721.rs|token_by_index_after_burn',
    'examples/erc721-consecutive/tests/erc721_consecutive.rs|burns',
    'examples/erc721-wrapper/tests/erc721_wrapper.rs|withdraw_to_success',
    'examples/erc721-metadata/tests/erc721_metadata.rs|set_token_uri_before_mint',
    'examples/erc721-metadata/tests/erc721_metadata.rs|return_token_uri_after_burn_and_remint',
    'examples/upgradeable-beacon/tests/upgradeable-beacon.rs|upgrade_to',
    'examples/ownable-two-step/tests/ownable_two_step.rs|overwrite_previous_transfer_ownership',
);
my %unchecked = map { $_ => 1 } (
    'examples/ownable/tests/ownable.rs|prevents_non_owners_from_transferring',
    'examples/ownable/tests/ownable.rs|guards_against_stuck_state',
    'examples/ownable/tests/ownable.rs|prevents_non_owners_from_renouncement',
    'examples/ownable-two-step/tests/ownable_two_step.rs|transfer_ownership_reverts_when_not_owner',
    'examples/ownable-two-step/tests/ownable_two_step.rs|overwrite_previous_transfer_ownership',
    'examples/ownable-two-step/tests/ownable_two_step.rs|accept_ownership_reverts_when_not_pending_owner',
    'examples/ownable-two-step/tests/ownable_two_step.rs|renounce_ownership_reverts_when_not_owner',
    'examples/erc4626/tests/erc4626.rs|withdraw::maintains_state_consistency_after_failed_withdrawal',
    'examples/safe-erc20/tests/safe_erc20_erc1363_no_return.rs|reverts_on_transfer_and_call_relaxed',
    'examples/safe-erc20/tests/safe_erc20_erc1363_no_return.rs|reverts_on_transfer_from_and_call_relaxed',
    'examples/safe-erc20/tests/safe_erc20_erc1363_no_return.rs|reverts_on_approve_and_call_relaxed',
);

my @rows;
while (my $l = <$fh>) {
    chomp $l;
    next if $l eq '';
    my @f = split /\t/, $l, -1;
    die "bad field count (" . scalar(@f) . "): $l\n" unless @f == 7;
    push @rows, \@f;
}
close $fh;

@rows = sort { $a->[0] cmp $b->[0] or $a->[1] <=> $b->[1] } @rows;

# Per-file summary.
my %sum;
for my $r (@rows) {
    my $s = $sum{$r->[0]} //= { n => 0, s => 0, f => 0, rf => 0 };
    $s->{n}++;
    if ($r->[5] eq 'SUCCESS') { $s->{s}++ } else { $s->{f}++; $s->{rf}++ if $r->[6] =~ /return false/ }
}
my ($tn, $ts, $tf, $trf) = (0, 0, 0, 0);
print "| File | E2E tests | SUCCESS | FAILURE | of which `return false` |\n";
print "|---|---:|---:|---:|---:|\n";
for my $file (sort keys %sum) {
    my $s = $sum{$file};
    printf "| `%s` | %d | %d | %d | %d |\n", $file, $s->{n}, $s->{s}, $s->{f}, $s->{rf};
    $tn += $s->{n}; $ts += $s->{s}; $tf += $s->{f}; $trf += $s->{rf};
}
printf "| **Total (%d files)** | **%d** | **%d** | **%d** | **%d** |\n", scalar(keys %sum), $tn, $ts, $tf, $trf;

print "\n### Full table (490 rows)\n\n";
print "Tags in the Description column: `[mixed]` = FAILURE row whose body also asserts a successful call before the failing one; `[error type not checked]` = the expected error is never asserted (a `reverted_with(...)` result is discarded, or only `expect_err` is used).\n\n";
print "| Location (file:line) | Test (module::fn) | Contract under test | Description | Class | Expected error / selector / result |\n";
print "|---|---|---|---|---|---|\n";
for my $r (@rows) {
    my ($file, $line, $test, $contract, $desc, $class, $expected) = @$r;
    my $key = "$file|$test";
    my @tags;
    push @tags, '[mixed]' if $mixed{$key};
    push @tags, '[error type not checked]' if $unchecked{$key};
    $desc = join(' ', @tags) . ' ' . $desc if @tags;
    printf "| %s:%s | %s | %s | %s | %s | %s |\n", $file, $line, $test, $contract, $desc, $class, $expected;
}
